1	package com.example.starter.service;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.sql.Statement;
6	import java.sql.Timestamp;
7	import java.time.Instant;
8	import java.time.LocalDateTime;
9	import java.util.List;
10	import java.util.Optional;
11	
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.jdbc.core.RowMapper;
15	import org.springframework.jdbc.support.GeneratedKeyHolder;
16	import org.springframework.jdbc.support.KeyHolder;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.PlatformTransactionManager;
19	import org.springframework.transaction.annotation.Propagation;
20	import org.springframework.transaction.annotation.Transactional;
21	import org.springframework.transaction.support.TransactionTemplate;
22	
23	import com.example.starter.support.AppClock;
24	import com.example.starter.support.Fingerprints;
25	import com.example.starter.web.BusinessException;
26	import com.example.starter.web.ConflictException;
27	import com.example.starter.web.NotFoundException;
28	import com.example.starter.web.dto.ArrivalRequest;
29	import com.example.starter.web.dto.ArrivalResponse;
30	import com.example.starter.web.dto.CreateGeneratorDispatchRequest;
31	import com.example.starter.web.dto.DispatchTruckView;
32	import com.example.starter.web.dto.GeneratorDispatchView;
33	import com.example.starter.web.dto.LoadItem;
34	import com.example.starter.web.dto.ReassignRequest;
35	import com.example.starter.web.dto.ReassignResponse;
36	import com.example.starter.web.dto.TruckView;
37	
38	/**
39	 * 发电车组合调度服务：调度单引用未复电工单并冻结负荷清单与工单版本，组合多车且总容量须覆盖合计负荷；
40	 * 一车仅一个未结束占用，任一车冲突整单不派；下发30分钟（恰满触发）未全到场转到达超时；
41	 * 到场逐车唯一记录，全部确认才供电；超时可整体改派（已到场车保留、其余释放换新车、全方案原子切换）；
42	 * 工单合并或正式复电后原子撤销未结束调度并释放车辆，供电证据保留。
43	 */
44	@Service
45	public class GeneratorDispatchService {
46	
47	    /** 到达时限：下发后30分钟，恰满即判定超时。 */
48	    static final long ARRIVAL_LIMIT_MINUTES = 30L;
49	
50	    /** 调度单内部行。 */
51	    record DispatchRow(long id, long workOrderId, int orderVersion, int totalLoadKw, String status,
52	            int version, LocalDateTime dispatchedAt, Long supersededById) {
53	    }
54	
55	    private static final RowMapper<DispatchRow> ROW_MAPPER = (rs, rowNum) -> mapRow(rs);
56	
57	    private final JdbcTemplate jdbc;
58	    private final AppClock clock;
59	    private final WorkOrderStore store;
60	    private final GeneratorTruckService trucks;
61	    private final GenIdempotency idem;
62	    private final TransactionTemplate tx;
63	
64	    public GeneratorDispatchService(JdbcTemplate jdbc, AppClock clock, WorkOrderStore store,
65	            GeneratorTruckService trucks, GenIdempotency idem, PlatformTransactionManager txManager) {
66	        this.jdbc = jdbc;
67	        this.clock = clock;
68	        this.store = store;
69	        this.trucks = trucks;
70	        this.idem = idem;
71	        this.tx = new TransactionTemplate(txManager);
72	    }
73	
74	    private static DispatchRow mapRow(ResultSet rs) throws SQLException {
75	        long superseded = rs.getLong("superseded_by_id");
76	        Long supersededBy = rs.wasNull() ? null : superseded;
77	        return new DispatchRow(rs.getLong("id"), rs.getLong("work_order_id"), rs.getInt("order_version"),
78	                rs.getInt("total_load_kw"), rs.getString("status"), rs.getInt("version"),
79	                rs.getTimestamp("dispatched_at").toLocalDateTime(), supersededBy);
80	    }
81	
82	    /**
83	     * 组合调度：原子冻结负荷清单与工单版本并占用全车；车总容量须覆盖合计负荷（恰等合法），
84	     * 任一车不存在/停用/已占用则整单不派。
85	     */
86	    public GeneratorDispatchView create(CreateGeneratorDispatchRequest req) {
87	        if (req.truckIds().stream().distinct().count() != req.truckIds().size()) {
88	            throw new IllegalArgumentException("车辆列表不可重复");
89	        }
90	        String fingerprint = Fingerprints.structured(req.requestId(), req.workOrderId(), req.expectedVersion(),
91	                req.loads().stream().map(l -> List.of(l.userName(), l.loadKw())).toList(),
92	                req.truckIds(), req.dispatchedAt().toString());
93	        try {
94	            return tx.execute(status -> doCreate(req, fingerprint));
95	        } catch (DuplicateKeyException e) {
96	            return tx.execute(status -> idem.findReplay(req.requestId(), fingerprint, GeneratorDispatchView.class)
97	                    .orElseThrow(() -> new BusinessException("车辆占用并发冲突, 整单不派")));
98	        }
99	    }
100	
101	    private GeneratorDispatchView doCreate(CreateGeneratorDispatchRequest req, String fingerprint) {
102	        Optional<GeneratorDispatchView> replay =
103	                idem.findReplay(req.requestId(), fingerprint, GeneratorDispatchView.class);
104	        if (replay.isPresent()) {
105	            return replay.get();
106	        }
107	        OrderHead order = lockOrder(req.workOrderId());
108	        // 行锁串行化后复查幂等：并发同键请求在此重放首次冻结结果
109	        Optional<GeneratorDispatchView> replayAfterLock =
110	                idem.findReplay(req.requestId(), fingerprint, GeneratorDispatchView.class);
111	        if (replayAfterLock.isPresent()) {
112	            return replayAfterLock.get();
113	        }
114	        if (!"PENDING".equals(order.status()) && !"QUEUED".equals(order.status())
115	                && !"EXECUTING".equals(order.status())) {
116	            throw new BusinessException("工单状态不可发电车调度: " + order.status());
117	        }
118	        if (req.expectedVersion() != order.version()) {
119	            throw new ConflictException("工单版本冲突: 期望" + req.expectedVersion() + ", 实际" + order.version());
120	        }
121	        int totalLoad = req.loads().stream().mapToInt(LoadItem::loadKw).sum();
122	        int totalCapacity = 0;
123	        for (long truckId : req.truckIds()) {
124	            TruckView truck = trucks.lockTruck(truckId);
125	            if (!truck.available()) {
126	                throw new BusinessException("发电车不可用: " + truckId);
127	            }
128	            if (count("active_occupation", "truck_id = ?", truckId) > 0) {
129	                throw new BusinessException("发电车存在未结束占用: " + truckId);
130	            }
131	            totalCapacity += truck.capacityKw();
132	        }
133	        if (totalCapacity < totalLoad) {
134	            throw new BusinessException("车总容量" + totalCapacity + "kW不足覆盖合计负荷" + totalLoad + "kW");
135	        }
136	        LocalDateTime dispatchedAt = toLocal(req.dispatchedAt());
137	        long dispatchId = insertDispatch(req.workOrderId(), order.version(), totalLoad, "IN_PROGRESS",
138	                dispatchedAt);
139	        for (LoadItem load : req.loads()) {
140	            jdbc.update("INSERT INTO dispatch_load (dispatch_id, user_name, load_kw) VALUES (?,?,?)",
141	                    dispatchId, load.userName(), load.loadKw());
142	        }
143	        for (long truckId : req.truckIds()) {
144	            jdbc.update("INSERT INTO dispatch_truck (dispatch_id, truck_id, arrived_at) VALUES (?,?,NULL)",
145	                    dispatchId, truckId);
146	            jdbc.update("INSERT INTO active_occupation (truck_id, dispatch_id, occupied_at) VALUES (?,?,?)",
147	                    truckId, dispatchId, Timestamp.valueOf(clock.now()));
148	        }
149	        store.addEvent(req.workOrderId(), "GENERATOR_DISPATCH_CREATED",
150	                "发电车调度单" + dispatchId + "已下发, 合计负荷" + totalLoad + "kW, 车总容量" + totalCapacity + "kW");
151	        GeneratorDispatchView view = viewOf(dispatchId);
152	        idem.record(req.requestId(), fingerprint, "DISPATCH_CREATE", dispatchId, view);
153	        return view;
154	    }
155	
156	    /**
157	     * 到场确认：逐车唯一记录；全部到场才转供电并入账供电证据；超时/改派/撤销后的迟到到场只记事件不占车。
158	     */
159	    public ArrivalResponse arrive(long dispatchId, ArrivalRequest req) {
160	        String fingerprint = Fingerprints.structured(req.requestId(), dispatchId, req.expectedVersion(),
161	                req.truckId(), req.arrivedAt().toString());
162	        try {
163	            return tx.execute(status -> doArrive(dispatchId, req, fingerprint));
164	        } catch (DuplicateKeyException e) {
165	            return tx.execute(status -> idem.findReplay(req.requestId(), fingerprint, ArrivalResponse.class)
166	                    .orElseThrow(() -> e));
167	        }
168	    }
169	
170	    private ArrivalResponse doArrive(long dispatchId, ArrivalRequest req, String fingerprint) {
171	        Optional<ArrivalResponse> replay = idem.findReplay(req.requestId(), fingerprint, ArrivalResponse.class);
172	        if (replay.isPresent()) {
173	            return replay.get();
174	        }
175	        DispatchRow row = lockDispatch(dispatchId);
176	        row = transitionIfTimedOut(row);
177	        // 行锁串行化后复查幂等：并发同键请求在此重放首次冻结结果
178	        Optional<ArrivalResponse> replayAfterLock =
179	                idem.findReplay(req.requestId(), fingerprint, ArrivalResponse.class);
180	        if (replayAfterLock.isPresent()) {
181	            return replayAfterLock.get();
182	        }
183	        if (req.expectedVersion() != row.version()) {
184	            throw new ConflictException("调度单版本冲突: 期望" + req.expectedVersion() + ", 实际" + row.version());
185	        }
186	        LocalDateTime arrivedAt = toLocal(req.arrivedAt());
187	        ArrivalResponse response;
188	        if ("IN_PROGRESS".equals(row.status())) {
189	            Boolean arrived = jdbc.query(
190	                    "SELECT arrived_at IS NOT NULL FROM dispatch_truck WHERE dispatch_id = ? AND truck_id = ?",
191	                    rs -> rs.next() ? rs.getBoolean(1) : null, dispatchId, req.truckId());
192	            if (arrived == null) {
193	                throw new BusinessException("车辆不在调度单方案内: " + req.truckId());
194	            }
195	            if (arrived) {
196	                throw new BusinessException("车辆已记录到场, 逐车唯一: " + req.truckId());
197	            }
198	            jdbc.update("UPDATE dispatch_truck SET arrived_at = ? WHERE dispatch_id = ? AND truck_id = ?",
199	                    Timestamp.valueOf(arrivedAt), dispatchId, req.truckId());
200	            int remaining = count("dispatch_truck", "dispatch_id = ? AND arrived_at IS NULL", dispatchId);
201	            String newStatus = row.status();
202	            String outcome = "ARRIVED";
203	            if (remaining == 0) {
204	                newStatus = "SUPPLYING";
205	                outcome = "ALL_ARRIVED";
206	                jdbc.update("INSERT INTO supply_evidence (dispatch_id, work_order_id, total_load_kw, supplied_at)"
207	                        + " VALUES (?,?,?,?)", dispatchId, row.workOrderId(), row.totalLoadKw(),
208	                        Timestamp.valueOf(arrivedAt));
209	                store.addEvent(row.workOrderId(), "GENERATOR_SUPPLYING",
210	                        "调度单" + dispatchId + "全部到场, 供电" + row.totalLoadKw() + "kW");
211	            }
212	            jdbc.update("UPDATE generator_dispatch SET status = ?, version = version + 1 WHERE id = ?",
213	                    newStatus, dispatchId);
214	            response = new ArrivalResponse(dispatchId, req.truckId(), outcome, newStatus,
215	                    row.version() + 1, arrivedAt);
216	        } else if ("SUPPLYING".equals(row.status())) {
217	            throw new BusinessException("调度单已全部到场供电, 重复到场拒绝: " + req.truckId());
218	        } else {
219	            // 超时/改派/撤销后的迟到到场：只记事件，不再次占车、不变更版本
220	            jdbc.update("INSERT INTO late_report_event (work_order_id, event_type, detail, created_at)"
221	                    + " VALUES (?,?,?,?)",
222	                    row.workOrderId(), "LATE_TRUCK_ARRIVAL",
223	                    "调度单" + dispatchId + "状态" + row.status() + ", 车辆" + req.truckId() + "迟到到场仅记事件",
224	                    Timestamp.valueOf(clock.now()));
225	            response = new ArrivalResponse(dispatchId, req.truckId(), "LATE", row.status(), row.version(),
226	                    arrivedAt);
227	        }
228	        idem.record(req.requestId(), fingerprint, "DISPATCH_ARRIVAL", dispatchId, response);
229	        return response;
230	    }
231	
232	    /**
233	     * 整体改派：仅到达超时的调度单可改派；已到场车保留在新方案，其余释放并换为新车，全方案原子切换。
234	     */
235	    public ReassignResponse reassign(long dispatchId, ReassignRequest req) {
236	        if (req.newTruckIds().stream().distinct().count() != req.newTruckIds().size()) {
237	            throw new IllegalArgumentException("车辆列表不可重复");
238	        }
239	        String fingerprint = Fingerprints.structured(req.requestId(), dispatchId, req.expectedVersion(),
240	                req.newTruckIds(), req.dispatchedAt().toString());
241	        try {
242	            return tx.execute(status -> doReassign(dispatchId, req, fingerprint));
243	        } catch (DuplicateKeyException e) {
244	            return tx.execute(status -> idem.findReplay(req.requestId(), fingerprint, ReassignResponse.class)
245	                    .orElseThrow(() -> new BusinessException("车辆占用并发冲突, 整单不改派")));
246	        }
247	    }
248	
249	    private ReassignResponse doReassign(long dispatchId, ReassignRequest req, String fingerprint) {
250	        Optional<ReassignResponse> replay = idem.findReplay(req.requestId(), fingerprint, ReassignResponse.class);
251	        if (replay.isPresent()) {
252	            return replay.get();
253	        }
254	        DispatchRow snapshot = findDispatch(dispatchId)
255	                .orElseThrow(() -> new NotFoundException("调度单不存在: " + dispatchId));
256	        OrderHead order = lockOrder(snapshot.workOrderId());
257	        DispatchRow row = lockDispatch(dispatchId);
258	        row = transitionIfTimedOut(row);
259	        // 行锁串行化后复查幂等：并发同键请求在此重放首次冻结结果
260	        Optional<ReassignResponse> replayAfterLock =
261	                idem.findReplay(req.requestId(), fingerprint, ReassignResponse.class);
262	        if (replayAfterLock.isPresent()) {
263	            return replayAfterLock.get();
264	        }
265	        if (!"TIMED_OUT".equals(row.status())) {
266	            throw new BusinessException("仅到达超时的调度单可整体改派: " + row.status());
267	        }
268	        if (req.expectedVersion() != row.version()) {
269	            throw new ConflictException("调度单版本冲突: 期望" + req.expectedVersion() + ", 实际" + row.version());
270	        }
271	        List<Long> kept = jdbc.query(
272	                "SELECT truck_id FROM dispatch_truck WHERE dispatch_id = ? AND arrived_at IS NOT NULL"
273	                + " ORDER BY truck_id",
274	                (rs, rowNum) -> rs.getLong(1), dispatchId);
275	        List<Long> released = jdbc.query(
276	                "SELECT truck_id FROM dispatch_truck WHERE dispatch_id = ? AND arrived_at IS NULL"
277	                + " ORDER BY truck_id",
278	                (rs, rowNum) -> rs.getLong(1), dispatchId);
279	        if (req.newTruckIds().stream().anyMatch(kept::contains)) {
280	            throw new BusinessException("新增车辆不可与已到场保留车重复");
281	        }
282	        int capacity = 0;
283	        for (long truckId : kept) {
284	            capacity += trucks.lockTruck(truckId).capacityKw();
285	        }
286	        for (long truckId : req.newTruckIds()) {
287	            TruckView truck = trucks.lockTruck(truckId);
288	            if (!truck.available()) {
289	                throw new BusinessException("发电车不可用: " + truckId);
290	            }
291	            if (count("active_occupation", "truck_id = ?", truckId) > 0) {
292	                throw new BusinessException("发电车存在未结束占用: " + truckId);
293	            }
294	            capacity += truck.capacityKw();
295	        }
296	        if (capacity < row.totalLoadKw()) {
297	            throw new BusinessException("新方案车总容量" + capacity + "kW不足覆盖合计负荷" + row.totalLoadKw() + "kW");
298	        }
299	        LocalDateTime dispatchedAt = toLocal(req.dispatchedAt());
300	        long newId = insertDispatch(row.workOrderId(), order.version(), row.totalLoadKw(), "IN_PROGRESS",
301	                dispatchedAt);
302	        List<LoadItem> loads = jdbc.query(
303	                "SELECT user_name, load_kw FROM dispatch_load WHERE dispatch_id = ? ORDER BY id",
304	                (rs, rowNum) -> new LoadItem(rs.getString(1), rs.getInt(2)), dispatchId);
305	        for (LoadItem load : loads) {
306	            jdbc.update("INSERT INTO dispatch_load (dispatch_id, user_name, load_kw) VALUES (?,?,?)",
307	                    newId, load.userName(), load.loadKw());
308	        }
309	        for (long truckId : kept) {
310	            LocalDateTime arrivedAt = jdbc.queryForObject(
311	                    "SELECT arrived_at FROM dispatch_truck WHERE dispatch_id = ? AND truck_id = ?",
312	                    (rs, rowNum) -> rs.getTimestamp(1).toLocalDateTime(), dispatchId, truckId);
313	            jdbc.update("INSERT INTO dispatch_truck (dispatch_id, truck_id, arrived_at) VALUES (?,?,?)",
314	                    newId, truckId, Timestamp.valueOf(arrivedAt));
315	            jdbc.update("UPDATE active_occupation SET dispatch_id = ? WHERE truck_id = ?", newId, truckId);
316	        }
317	        for (long truckId : req.newTruckIds()) {
318	            jdbc.update("INSERT INTO dispatch_truck (dispatch_id, truck_id, arrived_at) VALUES (?,?,NULL)",
319	                    newId, truckId);
320	            jdbc.update("INSERT INTO active_occupation (truck_id, dispatch_id, occupied_at) VALUES (?,?,?)",
321	                    truckId, newId, Timestamp.valueOf(clock.now()));
322	        }
323	        for (long truckId : released) {
324	            jdbc.update("DELETE FROM active_occupation WHERE truck_id = ?", truckId);
325	        }
326	        jdbc.update("UPDATE generator_dispatch SET status = 'REASSIGNED', superseded_by_id = ?,"
327	                + " version = version + 1 WHERE id = ?", newId, dispatchId);
328	        store.addEvent(row.workOrderId(), "GENERATOR_DISPATCH_REASSIGNED",
329	                "调度单" + dispatchId + "整体改派为" + newId + ", 保留已到场车" + kept + ", 释放" + released);
330	        ReassignResponse response = new ReassignResponse(dispatchId, newId, kept, released,
331	                req.newTruckIds(), "IN_PROGRESS", 1);
332	        idem.record(req.requestId(), fingerprint, "DISPATCH_REASSIGN", newId, response);
333	        return response;
334	    }
335	
336	    /**
337	     * 批量评估到达超时：下发满30分钟（恰满触发）未全到场的调度单转 TIMED_OUT，返回本次转换的调度单ID。
338	     */
339	    @Transactional(propagation = Propagation.REQUIRED)
340	    public List<Long> evaluateTimeouts() {
341	        List<Long> candidates = jdbc.query(
342	                "SELECT id FROM generator_dispatch WHERE status = 'IN_PROGRESS' ORDER BY id",
343	                (rs, rowNum) -> rs.getLong(1));
344	        return candidates.stream().filter(this::evaluateTimeout).toList();
345	    }
346	
347	    /**
348	     * 评估单个调度单是否到达超时；恰满30分钟未全到场即转换。
349	     *
350	     * @return true 表示本次调用发生了超时转换
351	     */
352	    @Transactional(propagation = Propagation.REQUIRED)
353	    public boolean evaluateTimeout(long dispatchId) {
354	        Optional<DispatchRow> found = findDispatch(dispatchId);
355	        if (found.isEmpty() || !"IN_PROGRESS".equals(found.get().status())) {
356	            return false;
357	        }
358	        DispatchRow before = lockDispatch(dispatchId);
359	        return !transitionIfTimedOut(before).status().equals(before.status());
360	    }
361	
362	    /**
363	     * 工单合并或正式复电后：原子撤销未结束调度并释放车辆，供电证据保留。返回撤销的调度单数。
364	     */
365	    @Transactional(propagation = Propagation.REQUIRED)
366	    public int cancelForWorkOrder(long workOrderId, String reason) {
367	        List<DispatchRow> open = jdbc.query(
368	                "SELECT * FROM generator_dispatch WHERE work_order_id = ?"
369	                + " AND status IN ('IN_PROGRESS','SUPPLYING','TIMED_OUT') FOR UPDATE",
370	                ROW_MAPPER, workOrderId);
371	        for (DispatchRow row : open) {
372	            jdbc.update("UPDATE generator_dispatch SET status = 'CANCELLED', version = version + 1"
373	                    + " WHERE id = ?", row.id());
374	            jdbc.update("DELETE FROM active_occupation WHERE dispatch_id = ?", row.id());
375	            store.addEvent(workOrderId, "GENERATOR_DISPATCH_CANCELLED",
376	                    "调度单" + row.id() + "因" + reason + "撤销, 车辆已释放, 供电证据保留");
377	        }
378	        return open.size();
379	    }
380	
381	    /**
382	     * 调度单详情：查询前评估到达超时。
383	     */
384	    public GeneratorDispatchView view(long dispatchId) {
385	        return tx.execute(status -> {
386	            evaluateTimeout(dispatchId);
387	            return viewOf(dispatchId);
388	        });
389	    }
390	
391	    /**
392	     * 工单视角的调度单列表（按ID升序）；工单不存在抛404。
393	     */
394	    public List<GeneratorDispatchView> listByWorkOrder(long workOrderId) {
395	        return tx.execute(status -> {
396	            store.requireById(workOrderId);
397	            evaluateTimeouts();
398	            return jdbc.query("SELECT id FROM generator_dispatch WHERE work_order_id = ? ORDER BY id",
399	                    (rs, rowNum) -> rs.getLong(1), workOrderId).stream()
400	                    .map(this::viewOf).toList();
401	        });
402	    }
403	
404	    private GeneratorDispatchView viewOf(long dispatchId) {
405	        DispatchRow row = findDispatch(dispatchId)
406	                .orElseThrow(() -> new NotFoundException("调度单不存在: " + dispatchId));
407	        List<LoadItem> loads = jdbc.query(
408	                "SELECT user_name, load_kw FROM dispatch_load WHERE dispatch_id = ? ORDER BY id",
409	                (rs, rowNum) -> new LoadItem(rs.getString(1), rs.getInt(2)), dispatchId);
410	        List<DispatchTruckView> truckViews = jdbc.query(
411	                "SELECT dt.truck_id, t.capacity_kw, dt.arrived_at FROM dispatch_truck dt"
412	                + " JOIN generator_truck t ON t.id = dt.truck_id WHERE dt.dispatch_id = ?"
413	                + " ORDER BY dt.truck_id",
414	                (rs, rowNum) -> {
415	                    Timestamp arrived = rs.getTimestamp(3);
416	                    return new DispatchTruckView(rs.getLong(1), rs.getInt(2),
417	                            arrived == null ? null : arrived.toLocalDateTime());
418	                }, dispatchId);
419	        List<Timestamp> supplied = jdbc.query(
420	                "SELECT supplied_at FROM supply_evidence WHERE dispatch_id = ?",
421	                (rs, rowNum) -> rs.getTimestamp(1), dispatchId);
422	        int totalCapacity = truckViews.stream().mapToInt(DispatchTruckView::capacityKw).sum();
423	        return new GeneratorDispatchView(row.id(), row.workOrderId(), row.orderVersion(), row.status(),
424	                row.version(), row.totalLoadKw(), totalCapacity, row.dispatchedAt(), loads, truckViews,
425	                supplied.isEmpty() ? null : supplied.get(0).toLocalDateTime(), row.supersededById());
426	    }
427	
428	    /** 若已到达超时则转换状态并返回最新行，否则原样返回。调用方须已持有行锁。 */
429	    private DispatchRow transitionIfTimedOut(DispatchRow row) {
430	        if (!"IN_PROGRESS".equals(row.status())) {
431	            return row;
432	        }
433	        if (clock.now().isBefore(row.dispatchedAt().plusMinutes(ARRIVAL_LIMIT_MINUTES))) {
434	            return row;
435	        }
436	        jdbc.update("UPDATE generator_dispatch SET status = 'TIMED_OUT', version = version + 1 WHERE id = ?",
437	                row.id());
438	        store.addEvent(row.workOrderId(), "GENERATOR_DISPATCH_TIMEOUT",
439	                "调度单" + row.id() + "下发满30分钟未全到场, 转到达超时");
440	        return lockDispatch(row.id());
441	    }
442	
443	    private DispatchRow lockDispatch(long dispatchId) {
444	        List<DispatchRow> rows = jdbc.query(
445	                "SELECT * FROM generator_dispatch WHERE id = ? FOR UPDATE", ROW_MAPPER, dispatchId);
446	        if (rows.isEmpty()) {
447	            throw new NotFoundException("调度单不存在: " + dispatchId);
448	        }
449	        return rows.get(0);
450	    }
451	
452	    private Optional<DispatchRow> findDispatch(long dispatchId) {
453	        List<DispatchRow> rows = jdbc.query(
454	                "SELECT * FROM generator_dispatch WHERE id = ?", ROW_MAPPER, dispatchId);
455	        return rows.stream().findFirst();
456	    }
457	
458	    /** 工单头：状态与版本。 */
459	    private record OrderHead(String status, int version) {
460	    }
461	
462	    /** 锁定工单行并返回状态与版本；不存在抛404。 */
463	    private OrderHead lockOrder(long workOrderId) {
464	        List<OrderHead> rows = jdbc.query(
465	                "SELECT status, version FROM work_order WHERE id = ? FOR UPDATE",
466	                (rs, rowNum) -> new OrderHead(rs.getString(1), rs.getInt(2)), workOrderId);
467	        if (rows.isEmpty()) {
468	            throw new NotFoundException("工单不存在: " + workOrderId);
469	        }
470	        return rows.get(0);
471	    }
472	
473	    private long insertDispatch(long workOrderId, int orderVersion, int totalLoadKw, String status,
474	            LocalDateTime dispatchedAt) {
475	        KeyHolder keys = new GeneratedKeyHolder();
476	        jdbc.update(con -> {
477	            var ps = con.prepareStatement(
478	                    "INSERT INTO generator_dispatch (work_order_id, order_version, total_load_kw, status,"
479	                    + " version, dispatched_at, created_at) VALUES (?,?,?,?,1,?,?)",
480	                    Statement.RETURN_GENERATED_KEYS);
481	            ps.setLong(1, workOrderId);
482	            ps.setInt(2, orderVersion);
483	            ps.setInt(3, totalLoadKw);
484	            ps.setString(4, status);
485	            ps.setTimestamp(5, Timestamp.valueOf(dispatchedAt));
486	            ps.setTimestamp(6, Timestamp.valueOf(clock.now()));
487	            return ps;
488	        }, keys);
489	        return keys.getKey().longValue();
490	    }
491	
492	    private int count(String table, String where, Object... args) {
493	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM " + table + " WHERE " + where,
494	                Integer.class, args);
495	        return n == null ? 0 : n;
496	    }
497	
498	    private LocalDateTime toLocal(Instant instant) {
499	        return LocalDateTime.ofInstant(instant, AppClock.ZONE);
500	    }
501	}
