94	        priorRoles.add(req.role());
95	        if (!(priorRoles.contains("DISPATCHER") && priorRoles.contains("FIELD"))) {
96	            return new RestoreConfirmResponse(req.workOrderId(), false, false, "EXECUTING", false);
97	        }
98	        // 双确认齐全：复电与负荷恢复记录在同一事务内完成
99	        BigDecimal loadKw = jdbc.queryForObject(
100	                "SELECT load_kw FROM restore_confirmation WHERE work_order_id = ? AND confirmer_role = 'FIELD'",
101	                BigDecimal.class, req.workOrderId());
