                "gd-7", order, 1L, List.of(new LoadItem("市一医院", 500)), List.of(t1), D0)));
        GeneratorDispatchView first = dispatches.create(new CreateGeneratorDispatchRequest(
                "gd-7", order, 1L, List.of(new LoadItem("市一医院", 500)), List.of(t1, t2), D0));

