/**
 * 正式复电或工单合并：与原调度取消规则同事务关闭未结束接替（WAITING/SWITCHED）并释放其全部车辆占用。
 * 调用方须已在事务内；行锁顺序保持“调度单→接替单→车辆”。
 */
@Transactional(propagation = Propagation.REQUIRED)
public int cancelForWorkOrder(long workOrderId, String reason) {
    List<Long> dispatchIds = jdbc.query(
            "SELECT id FROM generator_dispatch WHERE work_order_id = ?"
            + " AND status IN ('IN_PROGRESS','SUPPLYING','TIMED_OUT') FOR UPDATE",
            (rs, rowNum) -> rs.getLong(1), workOrderId);
    int cancelled = 0;
    for (long dispatchId : dispatchIds) {
        List<ReplacementRow> open = jdbc.query(
                "SELECT * FROM standby_replacement WHERE dispatch_id = ?"
                + " AND status IN ('WAITING','SWITCHED') FOR UPDATE",
                REPLACEMENT_MAPPER, dispatchId);
        for (ReplacementRow row : open) {
            List<Long> truckIds = replacementTruckIds(row.id());
            for (long truckId : truckIds) {
                jdbc.update("DELETE FROM active_occupation WHERE truck_id = ?", truckId);
            }
            jdbc.update("UPDATE standby_replacement SET status = 'CANCELLED', version = version + 1"
                    + " WHERE id = ?", row.id());
            store.addEvent(workOrderId, "STANDBY_REPLACEMENT_CANCELLED",
                    "接替单" + row.id() + "因" + reason + "关闭, 热备车" + truckIds + "已释放");
            cancelled++;
        }
    }
    return cancelled;
}

