406	     * 调用方须已持有调度单与接替单行锁。
407	     */
408	    private void switchComposition(ReplacementRow row, LocalDateTime switchedAt) {
409	        SupplyDispatch dispatch = lockDispatch(row.dispatchId());
410	        if (!"SUPPLYING".equals(dispatch.status())) {
411	            // 复电/合并竞争胜出：拒绝切入，事务回滚不留孤立占用
412	            throw new BusinessException("调度单已不处于供电中, 禁止切换: " + dispatch.status());
413	        }
414	        List<Long> newTruckIds = jdbc.query(
415	                "SELECT truck_id FROM replacement_truck WHERE replacement_id = ? ORDER BY truck_id",
416	                (rs, rowNum) -> rs.getLong(1), row.id());
417	        List<long[]> beforeRows = jdbc.query(
418	                "SELECT t.id, t.capacity_kw FROM dispatch_truck dt JOIN generator_truck t"
419	                + " ON t.id = dt.truck_id WHERE dt.dispatch_id = ? ORDER BY t.id",
420	                (rs, rowNum) -> new long[] {rs.getLong(1), rs.getInt(2)}, row.dispatchId());
421	        List<Long> beforeTruckIds = beforeRows.stream().map(a -> a[0]).toList();
422	        int beforeCapacity = beforeRows.stream().mapToInt(a -> (int) a[1]).sum();
423	        if (!beforeTruckIds.contains(row.oldTruckId())) {
424	            throw new BusinessException("旧车已不在供电组合内, 切换拒绝: " + row.oldTruckId());
425	        }
426	        for (long truckId : newTruckIds) {
427	            String type = jdbc.queryForObject(
428	                    "SELECT occupation_type FROM active_occupation WHERE truck_id = ?",
429	                    String.class, truckId);
430	            if (!"STANDBY".equals(type)) {
431	                throw new BusinessException("热备新车预占已丢失, 切换拒绝: " + truckId);
432	            }
433	        }
434	        int afterCapacity = beforeCapacity - row.oldCapacityKw() + row.newCapacityKw();
435	        if (beforeCapacity < row.frozenLoadKw() || afterCapacity < row.frozenLoadKw()) {
436	            throw new BusinessException("切换前后容量均须覆盖冻结负荷" + row.frozenLoadKw() + "kW: 前"
437	                    + beforeCapacity + "kW, 后" + afterCapacity + "kW");
438	        }
439	        // 旧车退出供电组合并释放；新车预占转供电占用并入组合（到场时刻随车转移）
440	        jdbc.update("DELETE FROM dispatch_truck WHERE dispatch_id = ? AND truck_id = ?",
441	                row.dispatchId(), row.oldTruckId());
442	        jdbc.update("DELETE FROM active_occupation WHERE truck_id = ? AND occupation_type = 'SUPPLY'"
443	                + " AND dispatch_id = ?", row.oldTruckId(), row.dispatchId());
444	        for (long truckId : newTruckIds) {
445	            LocalDateTime arrivedAt = jdbc.queryForObject(
446	                    "SELECT arrived_at FROM replacement_truck WHERE replacement_id = ? AND truck_id = ?",
447	                    (rs, rowNum) -> rs.getTimestamp(1).toLocalDateTime(), row.id(), truckId);
448	            jdbc.update("INSERT INTO dispatch_truck (dispatch_id, truck_id, arrived_at) VALUES (?,?,?)",
449	                    row.dispatchId(), truckId, Timestamp.valueOf(arrivedAt));
450	            jdbc.update("UPDATE active_occupation SET occupation_type = 'SUPPLY', dispatch_id = ?,"
451	                    + " replacement_id = NULL WHERE truck_id = ?", row.dispatchId(), truckId);
452	        }
